"""Data models for LLM interactions and generation results."""

from typing import Optional
from pydantic import BaseModel, Field


class GeneratedArtifacts(BaseModel):
    """The 5 core source and documentation artifacts generated by the LLM."""

    brute_code: str = Field(
        description="Standard C++17 brute-force/naive reference solution used as the oracle."
    )
    optimized_code: str = Field(
        description="Standard C++17 optimized solution expected to pass all subtasks within time/memory limits."
    )
    generator_code: str = Field(
        description="Standard C++17 testcase generator accepting command-line args: argv[1]=seed, argv[2]=subtask_id."
    )
    validator_code: str = Field(
        description="Standard C++17 independent testcase validator checking all constraints. Exits 0 on valid input, non-zero on invalid."
    )
    explanation_markdown: str = Field(
        description="Comprehensive algorithmic explanation, time/space complexity analysis, and correctness proof in Markdown."
    )


class LLMGenerationRequest(BaseModel):
    """Parameters for an LLM generation request."""

    problem_statement: str = Field(
        description="Full problem statement content in Markdown."
    )
    problem_id: str = Field(
        default="problem",
        description="Identifier or name of the problem."
    )
    model_name: str = Field(
        default="gemini-3.8-flash",
        description="Target LLM model name (e.g. gemini-3.8-flash, gemini-2.5-flash)."
    )
    temperature: float = Field(
        default=0.2,
        ge=0.0,
        le=1.0,
        description="Sampling temperature (low values encourage deterministic code)."
    )
    system_prompt: Optional[str] = Field(
        default=None,
        description="Optional override for the system instructions."
    )


class LLMUsageRecord(BaseModel):
    """Token consumption and cost estimation."""

    prompt_tokens: int = Field(default=0, description="Number of tokens in the input prompt.")
    candidates_tokens: int = Field(default=0, description="Number of tokens in the generated response.")
    total_tokens: int = Field(default=0, description="Total tokens processed.")
    estimated_cost_usd: float = Field(default=0.0, description="Estimated total API cost in USD.")
    latency_ms: float = Field(default=0.0, description="Request duration in milliseconds.")


class LLMGenerationResult(BaseModel):
    """Encapsulates the complete response from an LLM provider."""

    problem_id: str
    model_name: str
    artifacts: GeneratedArtifacts
    usage: LLMUsageRecord = Field(default_factory=LLMUsageRecord)
    is_cached: bool = False
    cache_key: Optional[str] = None
